public static String joinWith(String delimiter, List<String> lines) {
    if (lines.size() == 0) {
        return EMPTY;
    }
    int i = 0;
    StringBuilder sb = new StringBuilder();
    for (String line : lines) {
        if (i++ > 0) {
            sb.append(delimiter);
        }
        sb.append(line);
    }
    return sb.toString();
}
